#!/usr/bin/env bash
# Pulls the DB/Redis/SQS values that Terraform generated (and stored in AWS
# Secrets Manager / outputs) and materializes them as the Kubernetes Secret
# that the GitOps manifests expect (gitops/base/secrets.yaml only ships a
# placeholder — real values never go into git).
#
# Deliberately kept out of Argo CD's sync scope: secrets are regenerated by
# Terraform on every environment rebuild, so they don't belong in the
# GitOps repo. Run this once after `terraform apply` and again if RDS/Redis
# get recreated.
set -euo pipefail

cd "$(dirname "$0")/.."

# Don't rely on the caller's AWS CLI default region (`aws configure get
# region`) — it may point elsewhere (e.g. us-west-2) while every resource
# here lives in the region Terraform actually deployed to.
AWS_REGION="${AWS_REGION:-us-east-1}"

AUTH_DB_URL=$(aws secretsmanager get-secret-value --region "$AWS_REGION" --secret-id togglemaster/auth/database-url --query SecretString --output text | jq -r .database_url)
FLAG_DB_URL=$(aws secretsmanager get-secret-value --region "$AWS_REGION" --secret-id togglemaster/flag/database-url --query SecretString --output text | jq -r .database_url)
TARGETING_DB_URL=$(aws secretsmanager get-secret-value --region "$AWS_REGION" --secret-id togglemaster/targeting/database-url --query SecretString --output text | jq -r .database_url)

REDIS_HOST=$(terraform output -raw redis_primary_endpoint)
SQS_URL=$(terraform output -raw sqs_queue_url)
# --ignore-not-found tolera apenas ausência; erros de acesso/conexão abortam.
EXISTING_SECRET=$(kubectl get secret togglemaster-secrets -n togglemaster --ignore-not-found -o json)
preserve_or_generate_key() {
  local key_name="$1" encoded_value
  if [[ "${ROTATE_APP_KEYS:-false}" != "true" && -n "$EXISTING_SECRET" ]]; then
    encoded_value=$(jq -r --arg key "$key_name" '.data[$key] // empty' <<< "$EXISTING_SECRET")
    if [[ -n "$encoded_value" ]]; then
      printf '%s' "$encoded_value" | base64 -d
      return
    fi
  fi
  openssl rand -hex 32
}
MASTER_KEY=$(preserve_or_generate_key MASTER_KEY)
SERVICE_API_KEY=$(preserve_or_generate_key SERVICE_API_KEY)

kubectl create secret generic togglemaster-secrets \
  --namespace togglemaster \
  --from-literal=AUTH_DATABASE_URL="${AUTH_DB_URL}" \
  --from-literal=FLAG_DATABASE_URL="${FLAG_DB_URL}" \
  --from-literal=TARGETING_DATABASE_URL="${TARGETING_DB_URL}" \
  --from-literal=REDIS_URL="redis://${REDIS_HOST}:6379" \
  --from-literal=AWS_SQS_URL="${SQS_URL}" \
  --from-literal=MASTER_KEY="${MASTER_KEY}" \
  --from-literal=SERVICE_API_KEY="${SERVICE_API_KEY}" \
  --dry-run=client -o yaml | kubectl apply -f -

echo "Secret togglemaster-secrets applied to namespace togglemaster."

if [[ "${ROTATE_APP_KEYS:-false}" == "true" ]]; then
  echo "Chaves rotacionadas. Atualize os consumidores e reinicie os deployments via procedimento coordenado."
fi
